// F15: data helpers for the experiment page. The page reads the published forward-run results at
// public/data/self/forward.json (reports/self/forward.json in the repo), and the pre-registration hash at
// public/data/self/prereg.json. `loadForward` is pure over parsed JSON, so tests call it directly; the two
// *File helpers do the disk read and are what the page uses.
import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";

/** One paired task in the forward run, as published. `old` is the demoted setup, `new` the promoted one. */
export interface ForwardRow {
  task: string;
  old: boolean;
  new: boolean;
  costOld: number | null;
  costNew: number | null;
  /** Present when the task was excluded from the comparison, holding the written reason. */
  excluded?: string;
}

export interface ForwardSummary {
  n: number;
  /** The published sentence. The page shows it verbatim, never reworded. */
  wording: string;
  /** Rows loadForward rejected as malformed. They are not in `rows`. */
  skipped: number;
}

export interface Forward {
  rows: ForwardRow[];
  summary: ForwardSummary | null;
}

const DATA = join(process.cwd(), "public", "data");

const object = (v: unknown): Record<string, unknown> | null =>
  typeof v === "object" && v !== null && !Array.isArray(v) ? (v as Record<string, unknown>) : null;

/** A cost is a finite number, null, or absent (an unpriced task). Anything else makes the row malformed. */
function cost(v: unknown): { ok: true; value: number | null } | { ok: false } {
  if (v === undefined || v === null) return { ok: true, value: null };
  if (typeof v === "number" && Number.isFinite(v)) return { ok: true, value: v };
  return { ok: false };
}

/** A well-formed pair, or null. A row missing its task or its two pass flags is not a pair. */
function row(raw: unknown): ForwardRow | null {
  const r = object(raw);
  if (!r) return null;
  if (typeof r.task !== "string" || r.task.length === 0) return null;
  if (typeof r.old !== "boolean" || typeof r.new !== "boolean") return null;
  const oldCost = cost(r.costOld);
  const newCost = cost(r.costNew);
  if (!oldCost.ok || !newCost.ok) return null;
  if (r.excluded !== undefined && typeof r.excluded !== "string") return null;
  const out: ForwardRow = { task: r.task, old: r.old, new: r.new, costOld: oldCost.value, costNew: newCost.value };
  if (r.excluded !== undefined) out.excluded = r.excluded;
  return out;
}

/** The summary with the skip count added, or null when the file has no usable summary. */
function summary(raw: unknown, skipped: number): ForwardSummary | null {
  const s = object(raw);
  if (!s) return null;
  if (typeof s.n !== "number" || !Number.isFinite(s.n) || typeof s.wording !== "string") return null;
  return { n: s.n, wording: s.wording, skipped };
}

/**
 * Parses a published forward.json. A row that is not a well-formed pair is dropped and counted in
 * `summary.skipped`. A missing or malformed summary gives null, so the page shows the rows without a claim.
 */
export function loadForward(json: unknown): Forward {
  const root = object(json);
  const rawRows = root && Array.isArray(root.rows) ? root.rows : [];
  const rows: ForwardRow[] = [];
  let skipped = 0;
  for (const raw of rawRows) {
    const normalized = row(raw);
    if (normalized) rows.push(normalized);
    else skipped++;
  }
  return { rows, summary: summary(root?.summary, skipped) };
}

function readJson(file: string): unknown {
  if (!existsSync(file)) return undefined;
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch {
    return undefined;
  }
}

/** The forward results under dataDir (default public/data), or null when the file is absent or unreadable. */
export function loadForwardFile(dataDir: string = DATA): Forward | null {
  const json = readJson(join(dataDir, "self", "forward.json"));
  return json === undefined ? null : loadForward(json);
}

const SHA256 = /^[0-9a-f]{64}$/i;
/** Keys the harness may publish the frozen backlog's hash under. Only a 64-hex value is ever shown. */
const SHA_KEYS = ["backlog_sha256", "backlogSha256", "sha256"] as const;

/**
 * The frozen backlog's sha256 from a prereg.json, or null. A value that is not a 64-hex string under a
 * recognised key is ignored, so a stray hash is never published as the backlog's.
 */
export function loadPrereg(json: unknown): string | null {
  const root = object(json);
  if (!root) return null;
  const nested = object(root.backlog);
  for (const key of SHA_KEYS) {
    const v = root[key] ?? nested?.[key];
    if (typeof v === "string" && SHA256.test(v)) return v.toLowerCase();
  }
  return null;
}

/** The frozen backlog's sha256 from prereg.json under dataDir, or null when it is absent or has no hash. */
export function loadPreregFile(dataDir: string = DATA): string | null {
  const json = readJson(join(dataDir, "self", "prereg.json"));
  return json === undefined ? null : loadPrereg(json);
}

import { join } from "node:path";
import type { Metadata } from "next";
import { GITHUB } from "@/components/LandingData";
import { loadForwardFile, loadPreregFile, type Forward, type ForwardRow } from "@/lib/forward";

export const metadata: Metadata = {
  title: "Experiment · Roster",
  description:
    "The pre-registered forward run: the frozen backlog, and every paired task as it lands.",
};

const DATA = join(process.cwd(), "public", "data");
const PREREG_URL = `${GITHUB}/blob/main/experiments/PREREGISTRATION.md`;

const pass = (v: boolean) => (v ? "pass" : "fail");
const usd = (v: number | null) => (v === null ? <span className="na">n/a</span> : `$${v.toFixed(2)}`);

function Pairs({ rows, summary }: { rows: ForwardRow[]; summary: Forward["summary"] }) {
  return (
    <section style={{ marginTop: 32 }}>
      <h2 style={{ fontSize: "1.15rem", margin: "0 0 12px" }}>Pairs</h2>
      {summary && (
        <div className="banner" style={{ color: "var(--fg)" }}>
          {summary.wording}
          <span className="sub">
            {summary.n} paired tasks · {rows.length} shown
            {summary.skipped > 0
              ? ` · ${summary.skipped} malformed row${summary.skipped === 1 ? "" : "s"} skipped`
              : ""}
          </span>
        </div>
      )}
      {rows.length === 0 ? (
        <div className="empty">No pairs have been graded yet.</div>
      ) : (
        <div className="scroll">
          <table>
            <thead>
              <tr>
                <th>Task</th>
                <th>Old setup</th>
                <th>New setup</th>
                <th>Old cost</th>
                <th>New cost</th>
                <th>Excluded</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((r, i) => (
                <tr key={`${r.task}-${i}`}>
                  <td>{r.task}</td>
                  <td>{pass(r.old)}</td>
                  <td>{pass(r.new)}</td>
                  <td className="num">{usd(r.costOld)}</td>
                  <td className="num">{usd(r.costNew)}</td>
                  <td>{r.excluded === undefined ? "none" : r.excluded}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

export default function ExperimentPage() {
  const forward = loadForwardFile(DATA);
  const sha256 = loadPreregFile(DATA);

  return (
    <>
      <h1>The experiment</h1>
      <p className="lede">
        Roster built itself with several agent setups, reviewed its own sessions, and promoted one setup. Before
        that review ran, we froze a backlog of new tasks and their acceptance tests. This page reports the forward
        run: every frozen task, run through both the demoted and the promoted setup, graded blind. The
        hypotheses, tests and stop rules are fixed in{" "}
        <a href={PREREG_URL} rel="noopener noreferrer">PREREGISTRATION.md</a>.
      </p>
      {sha256 && (
        <p className="meta">Frozen backlog sha256: {sha256}</p>
      )}
      {forward === null ? (
        <div className="empty">The forward run has not started</div>
      ) : (
        <Pairs rows={forward.rows} summary={forward.summary} />
      )}
    </>
  );
}

// F15: the experiment page's data helper.
// Fixture rows use the published shape checked in with this task's acceptance test
// (experiments/acceptance/F15/tests/acceptance/F15.test.ts), which is the real sample of what loadForward reads.
import { describe, expect, test } from "bun:test";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { loadForward, loadForwardFile, loadPrereg, loadPreregFile } from "../web/lib/forward.ts";

const ROOT = join(import.meta.dir, "..");

const pair = (task: string, old: boolean, new_: boolean, costOld: number | null, costNew: number | null) => ({
  task,
  old,
  new: new_,
  costOld,
  costNew,
});

describe("loadForward", () => {
  test("returns the summary wording verbatim and the parsed pairs", () => {
    const wording = "Forward run completed: 1 task";
    const result = loadForward({
      summary: { n: 1, wording },
      rows: [{ task: "task-1", old: true, new: false, costOld: 12.5, costNew: 9.25 }],
    });

    expect(result.summary?.wording).toBe(wording);
    expect(result.summary?.n).toBe(1);
    expect(result.summary?.skipped).toBe(0);
    expect(result.rows).toEqual([
      { task: "task-1", old: true, new: false, costOld: 12.5, costNew: 9.25 },
    ]);
  });

  test("skips malformed rows and counts them in summary.skipped", () => {
    const result = loadForward({
      summary: { n: 2, wording: "Forward run completed: 2 tasks" },
      rows: [
        pair("task-valid", false, true, null, 3.5),
        // missing task
        { old: true, new: false, costOld: null, costNew: null },
        // costOld is not a number or null
        { task: "task-bad-cost", old: true, new: false, costOld: "free", costNew: null },
      ],
    });

    expect(result.rows.map((r) => r.task)).toEqual(["task-valid"]);
    expect(result.summary?.skipped).toBe(2);
  });

  test("every malformed shape is dropped, never given a default", () => {
    const result = loadForward({
      rows: [
        null,
        "task-not-an-object",
        [],
        // no pass flags
        { task: "no-pass-flags", costOld: null, costNew: null },
        // pass flags are not booleans
        { task: "string-pass", old: "yes", new: true, costOld: null, costNew: null },
        // empty task id
        { task: "", old: true, new: false, costOld: null, costNew: null },
        // cost is not finite
        { task: "infinite-cost", old: true, new: false, costOld: null, costNew: Infinity },
        // excluded must be a string when present
        { task: "bad-excluded", old: true, new: false, costOld: null, costNew: null, excluded: 3 },
        pair("keeper", false, false, 1, 2),
      ],
    });

    expect(result.rows.map((r) => r.task)).toEqual(["keeper"]);
    expect(result.summary).toBeNull();
  });

  test("an unpriced task keeps null costs and lands in the table", () => {
    const [r] = loadForward({ rows: [{ task: "unpriced", old: true, new: true }] }).rows;
    expect(r).toEqual({ task: "unpriced", old: true, new: true, costOld: null, costNew: null });
  });

  test("an excluded task keeps its written reason", () => {
    const rows = loadForward({
      rows: [{ task: "invalidated", old: false, new: false, costOld: null, costNew: null, excluded: "architecture change" }],
    }).rows;
    expect(rows[0]?.excluded).toBe("architecture change");
  });

  test("a file with no summary still yields its rows", () => {
    const result = loadForward({ rows: [pair("task-1", true, false, null, null)] });
    expect(result.rows).toHaveLength(1);
    expect(result.summary).toBeNull();
  });

  test("a summary missing n or wording is rejected, not half-read", () => {
    expect(loadForward({ summary: { wording: "no count" }, rows: [] }).summary).toBeNull();
    expect(loadForward({ summary: { n: 3 }, rows: [] }).summary).toBeNull();
    expect(loadForward({ summary: "not an object", rows: [] }).summary).toBeNull();
  });

  test("json that is not an object gives no rows and no summary", () => {
    for (const bad of [null, undefined, 7, "text", [], true]) {
      expect(loadForward(bad)).toEqual({ rows: [], summary: null });
    }
  });

  test("a missing rows array is an empty run, not a crash", () => {
    expect(loadForward({ summary: { n: 0, wording: "Forward run completed: 0 tasks" } }).rows).toEqual([]);
  });
});

describe("loadForwardFile", () => {
  function withDataDir(fn: (dir: string) => void) {
    const dir = mkdtempSync(join(tmpdir(), "roster-forward-"));
    try {
      fn(dir);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  }

  test("null while the forward run has not started", () => {
    withDataDir((dir) => expect(loadForwardFile(dir)).toBeNull());
  });

  test("reads self/forward.json under the data dir", () => {
    withDataDir((dir) => {
      mkdirSync(join(dir, "self"));
      writeFileSync(
        join(dir, "self", "forward.json"),
        JSON.stringify({
          summary: { n: 1, wording: "Forward run completed: 1 task" },
          rows: [pair("task-1", true, false, 1.5, null)],
        }),
      );
      const result = loadForwardFile(dir);
      expect(result?.rows).toHaveLength(1);
      expect(result?.summary?.wording).toBe("Forward run completed: 1 task");
    });
  });

  test("a corrupt file is treated as absent, not as a crash", () => {
    withDataDir((dir) => {
      mkdirSync(join(dir, "self"));
      writeFileSync(join(dir, "self", "forward.json"), "{not json");
      expect(loadForwardFile(dir)).toBeNull();
    });
  });
});

describe("loadPrereg", () => {
  const hash = "ac682b239225a99f45ffb347e1e73aa6fe1aec3159abb0ea928ffa6ffc3c63c7";

  test("finds the frozen backlog hash under a recognised key", () => {
    expect(loadPrereg({ backlog_sha256: hash })).toBe(hash);
    expect(loadPrereg({ backlogSha256: hash })).toBe(hash);
    expect(loadPrereg({ sha256: hash })).toBe(hash);
    expect(loadPrereg({ backlog: { sha256: hash } })).toBe(hash);
  });

  test("normalises the hash and ignores anything that is not 64 hex", () => {
    expect(loadPrereg({ backlog_sha256: hash.toUpperCase() })).toBe(hash);
    expect(loadPrereg({ backlog_sha256: "not a hash" })).toBeNull();
    expect(loadPrereg({ backlog_sha256: hash.slice(0, 63) })).toBeNull();
    expect(loadPrereg({ acceptance_sha256: hash })).toBeNull();
    expect(loadPrereg({ backlog_sha256: 12 })).toBeNull();
  });

  test("no hash anywhere gives null", () => {
    for (const bad of [null, undefined, "text", 3, {}, []]) expect(loadPrereg(bad)).toBeNull();
  });
});

describe("loadPreregFile", () => {
  test("reads self/prereg.json when present, null when absent", () => {
    const dir = mkdtempSync(join(tmpdir(), "roster-prereg-"));
    try {
      expect(loadPreregFile(dir)).toBeNull();
      mkdirSync(join(dir, "self"));
      writeFileSync(join(dir, "self", "prereg.json"), JSON.stringify({ backlog_sha256: "ab".repeat(32) }));
      expect(loadPreregFile(dir)).toBe("ab".repeat(32));
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe("page source", () => {
  const page = readFileSync(join(ROOT, "web", "app", "experiment", "page.tsx"), "utf8");

  test("shows the empty state and the pre-registration link", () => {
    expect(page).toContain("The forward run has not started");
    expect(page).toContain("/blob/main/experiments/PREREGISTRATION.md");
  });

  test("shows the published wording verbatim, with no rewrite", () => {
    expect(page).toContain("{summary.wording}");
  });

  test("no em dashes", () => {
    expect(page).not.toContain("—");
  });
});
